"""The hand-written interest catalogue (source of app/src/main/assets/interests.json).

Each E(...) is one thing a person can love. Fields:
  id, name, theme, wiki (Wikipedia article for the tile photo), terms (comma separated match words)
  kw    TMDB keyword names, resolved to ids at build time (shows)
  g     TMDB genre ids (shows)
  n     Google News search query (default: the name)
  v     YouTube search query (videos); minutes default to 8, or 4 for food and music
  live  {kind, league|query|tag}
  also  extra themes the love is listed under (the first Popular tiles also live in their own tab)
  refine (label, [option, ...]) with option = dict(id, name, terms, espnTeam?, league?, query?, tag? (a Radio Browser tag), countries?)
COUNTRIES (below) tags the cuisines, music and sports that belong to particular countries (ISO 3166 codes); setup lists a
person's home and living countries' loves first, then the untagged world-generic ones, then the other countries'.
"""

MIN_BY_THEME = {"food": 4, "music": 4}


def E(id, name, theme, wiki, terms, kw=(), g=(), n=None, v=None, mins=None, live=None, also=(), refine=None):
    return dict(id=id, name=name, theme=theme, wiki=wiki, terms=[t.strip() for t in terms.split(",") if t.strip()],
                kw=list(kw), g=list(g), n=n, v=v, mins=mins, live=live, also=list(also), refine=refine)


def O(id, name, terms=None, **kw):
    return dict(id=id, name=name, terms=[t.strip() for t in (terms or name).split(",") if t.strip()], **kw)


def espn(league):
    return {"kind": "espn", "league": league}


def ytlive(q):
    return {"kind": "ytlive", "query": q}


def radio(tag):
    return {"kind": "radio", "tag": tag}


