# What a sport calls its start (setup's summary and follow-up say "match times" for tennis) and how its score reads ("sets": 6-3 4-6).
# Untagged sports say "start times" and show the score as both sides' totals.
LIVE_WORDS = {
    "football": {"startWord": "kick-off times"}, "womens-football": {"startWord": "kick-off times"}, "nfl": {"startWord": "kick-off times"},
    "rugby-union": {"startWord": "kick-off times"}, "rugby-league": {"startWord": "kick-off times"}, "afl": {"startWord": "kick-off times"},
    "tennis": {"startWord": "match times", "scoreStyle": "sets"}, "formula-1": {"startWord": "race times"}, "motogp": {"startWord": "race times"},
    "indycar-nascar": {"startWord": "race times"}, "golf": {"startWord": "tee times"},
}
for _e in CATALOGUE:
    _e["cc"] = COUNTRIES.get(_e["id"], [])
    if _e["id"] in LIVE_WORDS and _e["live"]:
        _e["live"] = dict(_e["live"], **LIVE_WORDS[_e["id"]])
